<?php
declare(strict_types=1);require_once __DIR__.'/../app/bootstrap.php';$u=require_auth();if(($u['role']??'')!=='expert'){http_response_code(403);exit('Experts only.');}$st=db()->prepare('SELECT er.*,b.full_name buyer_name,r.name region_name,d.name district_name,w.name ward_name FROM expert_requests er JOIN users b ON b.id=er.buyer_user_id JOIN locations_regions r ON r.code=er.region_code JOIN locations_districts d ON d.region_code=er.region_code AND d.code=er.district_code JOIN locations_wards w ON w.region_code=er.region_code AND w.district_code=er.district_code AND w.code=er.ward_code WHERE er.assigned_expert_user_id=? ORDER BY er.id DESC');$st->execute([(int)$u['id']]);$rows=$st->fetchAll();ob_start(); ?>
<div class="card pad reveal"><div class="kicker">Expert workspace</div><h1>Assigned requests</h1><p class="sub">Requests assigned to you by the Ardhi Way admin team.</p><div class="request-grid"><?php if(!$rows):?><p class="sub">No requests assigned yet.</p><?php endif;?><?php foreach($rows as $row):?><article class="request-card"><span class="pill ok"><?= h((string)$row['status']) ?></span><h3><?= h(ucwords(str_replace('_',' ',(string)$row['expert_type']))) ?></h3><p class="sub"><?= h((string)$row['region_name']) ?> · <?= h((string)$row['district_name']) ?> · <?= h((string)$row['ward_name']) ?></p><p><?= nl2br(h((string)$row['description'])) ?></p><?php if($row['admin_notes']):?><div class="instr-note"><?= nl2br(h((string)$row['admin_notes'])) ?></div><?php endif;?></article><?php endforeach;?></div></div>
<?php $content=ob_get_clean();$title='Expert assignments. Ardhi Way';require __DIR__.'/_layout.php';
